package local.plaincraft.greatwall.lifecycle;

import java.io.IOException;
import java.util.List;
import java.util.Optional;
import local.plaincraft.greatwall.generation.WallBodyBackfill;
import local.plaincraft.greatwall.model.WallTypes.*;

/** 只注入写盘故障，实际执行正式持久化和发布计数；不访问玩家世界。 */
public final class PersistFailureProbe {
    public static void main(String[] args) {
        net.minecraft.SharedConstants.tryDetectVersion();
        net.minecraft.server.Bootstrap.bootStrap();
        String h = "0".repeat(64);
        var plan = new ChunkWritePlan(new ChunkKey("minecraft:overworld", 1, 2), h, h,
                List.of(), List.of(), List.of(), List.of(), List.of(), List.of(), h);
        WallBodyBackfill.install(new WallBodyBackfill.PlanStore() {
            public Optional<ChunkWritePlan> read(ChunkKey owner) { return Optional.empty(); }
            public void write(ChunkWritePlan value) throws IOException { throw new IOException("probe-disk-denied"); }
        });
        long before = WallBodyBackfill.persistFailures();
        var publication = new StartupPlanPublication();
        publication.accept(plan, p -> {}, WallBodyBackfill::persist);
        long delta = WallBodyBackfill.persistFailures() - before;
        System.out.println("PERSIST_FAULT published=" + publication.published()
                + " failed=" + publication.failed() + " persistFailuresDelta=" + delta);
        if (publication.published() != 1 || publication.failed() != 0 || delta != 1)
            throw new AssertionError("源码行为已经变化，不能沿用旧审查结论");
        WallBodyBackfill.install(null);
    }
}

package local.plaincraft.greatwall.planning;

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** 原编译批次直接实测；主线程在前两项已启动时中断拥有者，统计其后启动的工作。 */
public final class OwnerCancelProbe {
    public static void main(String[] args) throws Exception {
        var entered = new CountDownLatch(2);
        var release = new CountDownLatch(1);
        var jobs = new AtomicInteger();
        var failure = new AtomicReference<Throwable>();
        var interruptedAtEnd = new AtomicBoolean();
        var owner = new Thread(() -> {
            try (var batch = new OwnerCompileBatch(8, 2)) {
                for (int i = 0; i < 8; i++) batch.add(() -> {
                    int n = jobs.incrementAndGet();
                    if (n <= 2) {
                        entered.countDown();
                        try { if (!release.await(5, TimeUnit.SECONDS)) throw new AssertionError("probe timeout"); }
                        catch (InterruptedException e) { throw new AssertionError(e); }
                    }
                });
                interruptedAtEnd.set(Thread.currentThread().isInterrupted());
            } catch (Throwable e) { failure.set(e); }
        }, "probe-owner");
        owner.setDaemon(true);
        owner.start();
        try {
            if (!entered.await(5, TimeUnit.SECONDS)) throw new AssertionError("workers not started");
            owner.interrupt();
        } finally { release.countDown(); }
        owner.join(5000);
        if (owner.isAlive() || failure.get() != null) throw new AssertionError("probe failed", failure.get());
        System.out.println("OWNER_INTERRUPT totalJobs=" + jobs.get() + " jobsStartedAfterInterrupt="
                + (jobs.get() - 2) + " ownerInterruptedAtEnd=" + interruptedAtEnd.get());
        if (jobs.get() != 8 || !interruptedAtEnd.get()) throw new AssertionError("源码行为已经变化");
    }
}
